// src/pages/SignUpPage/SignUpPage.jsx
import React, { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../../context/AuthContext';
import styles from './SignUpPage.module.css';
import { FaGoogle, FaFacebook, FaApple } from 'react-icons/fa';

export const SignUpPage = () => {
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const { signup } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    // Basic password validation
    if (password.length < 8) {
      setError('Password must be 8 characters or more');
      return;
    }
    if (email.toLowerCase().includes(password.toLowerCase())) {
      setError("Password must not include any part of your email");
      return;
    }
    // Simple check for common passwords (expand this list in production)
    const commonPasswords = ['password123', 'admin123', '12345678'];
    if (commonPasswords.includes(password.toLowerCase())) {
      setError("Don't use a common password");
      return;
    }

    try {
      // Split the name into firstName and lastName
      const nameParts = name.trim().split(' ');
      const firstName = nameParts[0];
      const lastName = nameParts.length > 1 ? nameParts.slice(1).join(' ') : '';

      console.log('Attempting to sign up with:', { firstName, lastName, email, password });

      // Try both formats to handle potential API inconsistencies
      // Format 1: firstName and lastName as separate fields (as per backend code)
      const userData = {
        firstName,
        lastName,
        email,
        password
      };

      console.log('Sending registration data:', userData);

      const result = await signup(userData);
      console.log('Signup successful:', result);

      navigate('/'); // Redirect to homepage after successful signup
    } catch (err) {
      console.error('Signup error:', err);

      // Provide more specific error messages based on the error type
      if (err.type === 'NETWORK_ERROR') {
        setError('Unable to connect to the server. Please check your internet connection.');
      } else if (err.type === 'VALIDATION_ERROR') {
        // Display the validation error message directly
        setError(err.message || 'Please check your input and try again.');

        // If it's a "User already exists" error, provide a link to login
        if (err.message && err.message.includes('already registered')) {
          setError(
            <>
              {err.message} <a href="/login" className={styles.loginLink}>Log in here</a>
            </>
          );
        }
      } else if (err.type === 'RATE_LIMIT_ERROR') {
        setError(err.message || 'Too many signup attempts. Please try again later.');
      } else {
        setError(err.message || 'An error occurred during signup. Please try again.');
      }
    }
  };

  const handleSocialLogin = (provider) => {
    alert(`Signing up with ${provider}... (Not implemented)`);
    // Future social login integration here
  };

  return (
    <div className={styles.signUpPage}>
      <div className={styles.formCard}>
        <h1>Join Now</h1>
        <p className={styles.alreadyHaveAccount}>
          Already have an account? <a href="/login">Log In</a>
        </p>
        <p className={styles.termsText}>
          By signing up, you confirm that you are 16 years of age or older and you agree to our{' '}
          <a href="/terms">Terms of Service</a> and <a href="/privacy">Privacy Policy</a>.
        </p>

        <div className={styles.socialButtons}>
          <button onClick={() => handleSocialLogin('Google')} className={styles.googleBtn}>
            <FaGoogle /> Connect with Google
          </button>
          <button onClick={() => handleSocialLogin('Facebook')} className={styles.facebookBtn}>
            <FaFacebook /> Connect with Facebook
          </button>
          <button onClick={() => handleSocialLogin('Apple')} className={styles.appleBtn}>
            <FaApple /> Connect with Apple
          </button>
        </div>

        <div className={styles.separator}>OR</div>

        <form className={styles.signUpForm} onSubmit={handleSubmit}>
          <div className={styles.formGroup}>
            <label>Name</label>
            <input
              type="text"
              placeholder="Name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              required
            />
          </div>
          <div className={styles.formGroup}>
            <label>Email Address</label>
            <input
              type="email"
              placeholder="Email Address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
          </div>
          <div className={styles.formGroup}>
            <label>Password</label>
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
          </div>
          <p className={styles.passwordRequirements}>
            Password must be 8 characters or more <br />
            Don’t use any part of your email <br />
            Don’t use a common password
          </p>
          {error && <p className={styles.error}>{error}</p>}
          <button type="submit" className={styles.signUpButton}>
            Sign Up
          </button>
        </form>
      </div>
    </div>
  );
};
